{"content":""""HTTP fetch implementation for the fixed local diagnostic manifest."""
import json
from pathlib import Path

import requests

_MANIFEST_PATH = Path(__file__).resolve().parent.parent / "diagnostics.json"


def _manifest_urls() -> frozenset[str]:
    return frozenset(json.loads(_MANIFEST_PATH.read_text(encoding="utf-8")))


def fetch(url: str) -> str:
    """GET a maintainer-listed diagnostic URL and return the UTF-8 body.

    Only URLs listed in the local ``diagnostics.json`` manifest are accepted;
    anything else is rejected. Normal redirects are followed.
    """
    if url not in _manifest_urls():
        raise ValueError(f"URL not in diagnostic manifest: {url}")
    response = requests.get(url, timeout=10)
    response.raise_for_status()
    return response.content.decode("utf-8")
